void AVLTree<T>::inorder(std::ostream &out) const {
    _inOrder(root, out);
}

//*****************************************************************************************************

template <typename T>
void AVLTree<T>::_inOrder(Node<T> *r, std::ostream &out) const {
    if (r) {
        _inOrder(r->left, out);
